REVOKE CREATE ON SCHEMA public FROM PUBLIC;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), issuer text NOT NULL, subject text NOT NULL, name text NOT NULL, UNIQUE(issuer,subject));
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid REFERENCES users NOT NULL, csrf text NOT NULL, expires_at timestamptz NOT NULL, amr jsonb NOT NULL DEFAULT '[]', auth_time bigint);
CREATE TABLE oauth_states(id text PRIMARY KEY, data jsonb NOT NULL, expires_at timestamptz NOT NULL);
GRANT SELECT,INSERT,UPDATE ON users TO ideator_auth;
GRANT SELECT,INSERT,DELETE ON sessions,oauth_states TO ideator_auth;
CREATE TABLE workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), created_by uuid REFERENCES users NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(workspace_id uuid REFERENCES workspaces NOT NULL, user_id uuid REFERENCES users NOT NULL, roles text[] NOT NULL CHECK(roles <@ ARRAY['member','admin','coordinator','reviewer','moderator']::text[] AND cardinality(roles)>0), revoked_at timestamptz, PRIMARY KEY(workspace_id,user_id));
CREATE FUNCTION actor() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.actor',true),'')::uuid $$;
CREATE FUNCTION member(w uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM memberships WHERE workspace_id=w AND user_id=actor() AND revoked_at IS NULL) $$;
CREATE FUNCTION has_role(w uuid,r text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM memberships WHERE workspace_id=w AND user_id=actor() AND revoked_at IS NULL AND r=ANY(roles)) $$;
REVOKE ALL ON FUNCTION member(uuid),has_role(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION member(uuid),has_role(uuid,text) TO ideator_app;
CREATE TABLE objects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid REFERENCES workspaces NOT NULL, type text NOT NULL CHECK(type IN ('claim','observation')), author_id uuid REFERENCES users NOT NULL, current_revision integer, next_revision integer NOT NULL DEFAULT 1, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id));
CREATE TABLE revisions(workspace_id uuid NOT NULL, object_id uuid NOT NULL, revision integer NOT NULL CHECK(revision>0), schema_version integer NOT NULL DEFAULT 1 CHECK(schema_version=1), content jsonb NOT NULL, origin text NOT NULL DEFAULT 'human' CHECK(origin='human'), actor_id uuid REFERENCES users NOT NULL, reason text NOT NULL, parent_revision integer, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,object_id,revision), FOREIGN KEY(workspace_id,object_id) REFERENCES objects(workspace_id,id), FOREIGN KEY(workspace_id,object_id,parent_revision) REFERENCES revisions(workspace_id,object_id,revision));
CREATE TABLE publications(workspace_id uuid NOT NULL, object_id uuid NOT NULL, revision integer NOT NULL, published_by uuid REFERENCES users NOT NULL, published_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,object_id,revision), FOREIGN KEY(workspace_id,object_id,revision) REFERENCES revisions(workspace_id,object_id,revision));
ALTER TABLE objects ADD FOREIGN KEY(workspace_id,id,current_revision) REFERENCES publications(workspace_id,object_id,revision) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE draft_heads(workspace_id uuid NOT NULL, object_id uuid NOT NULL, author_id uuid REFERENCES users NOT NULL, revision integer NOT NULL, base_revision integer, PRIMARY KEY(workspace_id,object_id,author_id), FOREIGN KEY(workspace_id,object_id,revision) REFERENCES revisions(workspace_id,object_id,revision));
CREATE TABLE project_objects(workspace_id uuid NOT NULL, project_id uuid NOT NULL, object_id uuid NOT NULL, PRIMARY KEY(workspace_id,project_id,object_id), FOREIGN KEY(workspace_id,object_id) REFERENCES objects(workspace_id,id));
CREATE TABLE projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid REFERENCES workspaces NOT NULL,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200),created_by uuid REFERENCES users NOT NULL,version integer NOT NULL DEFAULT 1, UNIQUE(workspace_id,id));
ALTER TABLE project_objects ADD FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id) ON DELETE CASCADE;
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid REFERENCES workspaces NOT NULL,actor_id uuid REFERENCES users NOT NULL,action text NOT NULL,target_id uuid,revision integer,request_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox(event_id uuid PRIMARY KEY REFERENCES audit_events,workspace_id uuid NOT NULL,kind text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),delivered_at timestamptz);
CREATE TABLE event_receipts(event_id uuid PRIMARY KEY REFERENCES outbox,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency(workspace_id uuid NOT NULL,actor_id uuid NOT NULL,route text NOT NULL,key uuid NOT NULL,hash text NOT NULL,response jsonb NOT NULL,status integer NOT NULL,etag text,expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours',PRIMARY KEY(workspace_id,actor_id,route,key));
CREATE INDEX objects_page ON objects(workspace_id,updated_at,id);
CREATE INDEX outbox_pending ON outbox(created_at) WHERE delivered_at IS NULL;
CREATE INDEX memberships_user ON memberships(user_id,workspace_id);
CREATE FUNCTION object_author(w uuid,o uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM objects WHERE workspace_id=w AND id=o AND author_id=actor()) $$;
CREATE FUNCTION published(w uuid,o uuid,r integer) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM publications WHERE workspace_id=w AND object_id=o AND revision=r) $$;
REVOKE ALL ON FUNCTION object_author(uuid,uuid),published(uuid,uuid,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION object_author(uuid,uuid),published(uuid,uuid,integer) TO ideator_app;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['workspaces','memberships','objects','revisions','publications','draft_heads','projects','project_objects','audit_events','outbox','idempotency'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 END LOOP;
END $$;
CREATE POLICY workspace_read ON workspaces FOR SELECT TO ideator_app USING(member(id) OR created_by=actor());
CREATE POLICY workspace_create ON workspaces FOR INSERT TO ideator_app WITH CHECK(created_by=actor());
CREATE POLICY workspace_update ON workspaces FOR UPDATE TO ideator_app USING(has_role(id,'admin')) WITH CHECK(has_role(id,'admin'));
CREATE POLICY membership_read ON memberships FOR SELECT TO ideator_app USING(member(workspace_id));
CREATE POLICY membership_write ON memberships FOR ALL TO ideator_app USING(has_role(workspace_id,'admin')) WITH CHECK(has_role(workspace_id,'admin') OR (user_id=actor() AND EXISTS(SELECT 1 FROM workspaces WHERE id=workspace_id AND created_by=actor()) AND NOT member(workspace_id)));
CREATE POLICY object_read ON objects FOR SELECT TO ideator_app USING(member(workspace_id) AND (author_id=actor() OR current_revision IS NOT NULL));
CREATE POLICY object_create ON objects FOR INSERT TO ideator_app WITH CHECK(member(workspace_id) AND author_id=actor());
CREATE POLICY object_edit ON objects FOR UPDATE TO ideator_app USING(member(workspace_id) AND author_id=actor()) WITH CHECK(member(workspace_id) AND author_id=actor());
CREATE POLICY revision_read ON revisions FOR SELECT TO ideator_app USING(member(workspace_id) AND (object_author(workspace_id,object_id) OR published(workspace_id,object_id,revision)));
CREATE POLICY revision_create ON revisions FOR INSERT TO ideator_app WITH CHECK(member(workspace_id) AND actor_id=actor() AND object_author(workspace_id,object_id));
CREATE POLICY publication_read ON publications FOR SELECT TO ideator_app USING(member(workspace_id));
CREATE POLICY publication_create ON publications FOR INSERT TO ideator_app WITH CHECK(member(workspace_id) AND published_by=actor() AND object_author(workspace_id,object_id));
CREATE POLICY draft_owner ON draft_heads TO ideator_app USING(member(workspace_id) AND author_id=actor()) WITH CHECK(member(workspace_id) AND author_id=actor() AND object_author(workspace_id,object_id));
CREATE POLICY project_read ON projects FOR SELECT TO ideator_app USING(member(workspace_id));
CREATE POLICY project_create ON projects FOR INSERT TO ideator_app WITH CHECK(member(workspace_id) AND created_by=actor());
CREATE POLICY project_update ON projects FOR UPDATE TO ideator_app USING(member(workspace_id) AND (created_by=actor() OR has_role(workspace_id,'coordinator'))) WITH CHECK(member(workspace_id));
CREATE POLICY project_delete ON projects FOR DELETE TO ideator_app USING(member(workspace_id) AND (created_by=actor() OR has_role(workspace_id,'coordinator')));
CREATE POLICY reference_read ON project_objects FOR SELECT TO ideator_app USING(member(workspace_id) AND EXISTS(SELECT 1 FROM objects WHERE id=object_id AND workspace_id=project_objects.workspace_id));
CREATE POLICY reference_write ON project_objects FOR ALL TO ideator_app USING(member(workspace_id) AND EXISTS(SELECT 1 FROM projects WHERE id=project_id AND (created_by=actor() OR has_role(workspace_id,'coordinator')))) WITH CHECK(member(workspace_id) AND EXISTS(SELECT 1 FROM projects WHERE id=project_id AND (created_by=actor() OR has_role(workspace_id,'coordinator'))) AND EXISTS(SELECT 1 FROM objects WHERE id=object_id AND current_revision IS NOT NULL));
CREATE POLICY audit_insert ON audit_events FOR INSERT TO ideator_app WITH CHECK(member(workspace_id) AND actor_id=actor());
CREATE POLICY outbox_insert ON outbox FOR INSERT TO ideator_app WITH CHECK(member(workspace_id));
CREATE POLICY idem_owner ON idempotency TO ideator_app USING(member(workspace_id) AND actor_id=actor()) WITH CHECK(member(workspace_id) AND actor_id=actor());
CREATE POLICY worker_outbox ON outbox TO ideator_worker USING(true) WITH CHECK(true);
GRANT USAGE ON SCHEMA public TO ideator_app,ideator_auth,ideator_worker;
GRANT SELECT,INSERT,UPDATE ON workspaces,memberships,objects,projects TO ideator_app;
GRANT DELETE ON projects TO ideator_app;
GRANT SELECT,INSERT ON revisions,publications TO ideator_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON draft_heads,project_objects,idempotency TO ideator_app;
GRANT INSERT ON audit_events,outbox TO ideator_app;
GRANT SELECT,UPDATE(delivered_at) ON outbox TO ideator_worker;
GRANT SELECT,INSERT ON event_receipts TO ideator_worker;
